// Stryker Trading Academy: /demo-hero (unlisted preview page)
//
// Behaviour for the four homepage-hero variations on demo-hero.html
// (markup generated by tools/demo-hero/gen.py).
//
//   pills     [data-pill="session"]: the trading session clock from
//             market-hours.js (StrykerMarketHours.sessionLabel), ticking each
//             second. It is a clock computed from session hours, never market
//             data. [data-pill="gex"]: "Free SPX GEX // updated N min ago" from
//             the public /api/gex/levels/SPX?dte=0 (market.options_ts, else
//             data_ts, else fetched_at). Never "live", "real-time" or "delayed".
//   free N    "1–10" comes from the Free plan's chapterAccess in Firestore
//             plans (same source as pricing-hero.js); the HTML ships 1–10.
//   enrolled  variation B shows "N traders enrolled" only when the real
//             publicStats/enrollment count loads (same doc main.js reads).
//   B tilt    the screenshot flattens as its hero scrolls toward the centre.
//   C reveal  headline words fade/rise in one by one when C is first seen.
//   D count   the big numbers count up once when first seen.
//   switcher  floating A/B/C/D; the chip of the variation in view lights up.
//
// Reduced motion: no tilt updates, no reveal, no count-up (CSS also stops the
// ticker, the wall lines and the pulsing dot). Loops pause off screen (.xh-off).

(function () {
  'use strict';
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var root = document.documentElement;

  // ------------------------------------------------------------ theme toggle
  var tb = $('#xh-theme');
  if (tb) tb.addEventListener('click', function () {
    if (typeof window.toggleStrykerTheme === 'function') { window.toggleStrykerTheme(); return; }
    var toDay = root.getAttribute('data-theme') !== 'light';
    if (toDay) root.setAttribute('data-theme', 'light'); else root.removeAttribute('data-theme');
    try { localStorage.setItem('stryker_theme', toDay ? 'day' : 'night'); } catch (e) {}
  });

  // copies of the site header: their menu buttons open their own links
  $$('.xh-nav-copy .nav-toggle').forEach(function (b) {
    b.addEventListener('click', function () {
      var links = b.closest('.nav').querySelector('.nav-links');
      if (links) links.classList.toggle('xh-open');
    });
  });

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function setPill(el, on, long, short) {
    el.classList.toggle('is-on', !!on);
    var t = $('.xh-pill-t', el);
    var html = '<span class="xh-l">' + esc(long) + '</span><span class="xh-s">' + esc(short || long) + '</span>';
    if (t.innerHTML !== html) t.innerHTML = html;
  }

  // ------------------------------------------------------------ session clock pill
  var sPills = $$('[data-pill="session"]');
  var MH = window.StrykerMarketHours;
  function upper(s) { return String(s).toUpperCase(); }
  function tickSession() {
    if (!MH || !MH.sessionLabel) return;
    var L = MH.sessionLabel(Date.now()), head, sHead;
    if (L.sessions.length === 1) { head = L.sessions[0] + ' session open'; }
    else if (L.sessions.length > 1) { head = L.sessions.join(' & ') + ' sessions open'; }
    else if (L.weekend) { head = 'Weekend: no session open'; }
    else { head = 'No session open'; }
    sHead = L.shortHead;
    var left = L.next ? MH.fmtClock(L.next.at - Date.now()) : '';
    var tail = L.next ? L.next.name + ' opens in ' + left : '';
    var sTail = L.next ? L.next.short + ' in ' + left : '';
    var long = upper(head) + (tail ? ' // ' + upper(tail) : '');
    var short = upper(sHead) + (sTail ? ' // ' + upper(sTail) : '');
    sPills.forEach(function (p) { setPill(p, L.open, long, short); });
  }
  if (sPills.length) {
    if (MH && MH.sessionLabel) { tickSession(); setInterval(tickSession, 1000); }
    else sPills.forEach(function (p) { setPill(p, false, 'Asia · London · New York sessions', 'Trading sessions'); });
  }

  // ------------------------------------------------------------ GEX freshness pill
  var gPills = $$('[data-pill="gex"]');
  if (gPills.length) {
    var gexAt = 0, closed = false;
    var ago = function () {
      var m = Math.max(0, Math.round((Date.now() / 1000 - gexAt) / 60));
      if (m < 60) return 'updated ' + m + ' min ago';
      var h = Math.floor(m / 60);
      return h < 48 ? 'updated ' + h + ' h ago' : 'updated ' + Math.floor(h / 24) + ' d ago';
    };
    var paint = function () {
      if (!gexAt) return;
      var a = ago();
      gPills.forEach(function (p) {
        setPill(p, !closed, 'FREE SPX GEX // ' + upper((closed ? 'last session, ' : '') + a), 'FREE SPX GEX // ' + upper(a));
      });
    };
    gPills.forEach(function (p) { setPill(p, false, 'FREE SPX GEX // CALL WALL · ZERO GAMMA · PUT WALL', 'FREE SPX GEX LEVELS'); });
    fetch('/api/gex/levels/SPX?dte=0', { cache: 'no-store' }).then(function (r) { return r.ok ? r.json() : null; }).then(function (d) {
      if (!d || d.call_wall == null) return;
      var m = d.market || {};
      gexAt = +m.options_ts || +m.data_ts || +d.fetched_at || 0;
      closed = !!(m.state && m.state !== 'open' && m.state !== 'stale');
      paint(); setInterval(paint, 30000);
    }).catch(function () {});
  }

  // ------------------------------------------------- Free plan range + enrolled
  function withDb(fn, tries) {
    tries = tries || 0;
    var ok = typeof firebase !== 'undefined' && firebase.apps && firebase.apps.length;
    if (ok) { try { fn(firebase.firestore()); } catch (e) {} return; }
    if (tries < 40) setTimeout(function () { withDb(fn, tries + 1); }, 150);
  }
  withDb(function (fdb) {
    fdb.collection('plans').get().then(function (snap) {
      var best = null;
      snap.forEach(function (doc) {
        var p = doc.data() || {};
        if (p.hidden || p.archived) return;
        var m = String(p.chapterAccess || '').match(/^(\d+)\s*-\s*(\d+)$/);
        if (m && (!best || +m[2] > +best[2])) best = m;
      });
      if (best) $$('.xh-freeN').forEach(function (el) { el.textContent = best[1] + '\u2013' + best[2]; });
    }).catch(function () {});
    fdb.collection('publicStats').doc('enrollment').get().then(function (doc) {
      var n = doc.exists ? Number(doc.data().count) : NaN;
      if (!isFinite(n) || n <= 0) return;
      $$('.xh-enrolled').forEach(function (el) { $('.xh-enrolled-n', el).textContent = Math.round(n).toLocaleString(); el.hidden = false; });
    }).catch(function () {});
  });

  // ------------------------------------------------------------ visibility
  var vars = $$('.xh-var'), chips = $$('.xh-switch a');
  function lightChip() {
    var line = window.innerHeight * 0.4, pick = 'A';
    vars.forEach(function (v) { var r = v.getBoundingClientRect(); if (r.top <= line) pick = v.id.slice(4); });
    chips.forEach(function (c) { c.classList.toggle('on', c.getAttribute('data-v') === pick); });
  }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (es) {
      es.forEach(function (en) { en.target.classList.toggle('xh-off', !en.isIntersecting); });
    }, { rootMargin: '60px 0px' });
    vars.forEach(function (v) { io.observe(v); });
  }

  // ------------------------------------------------------------ B tilt
  var shot = $('.xb-tilt'), bHero = $('.xb');
  function tilt() {
    if (!shot || reduced) return;
    var r = bHero.getBoundingClientRect(), vh = window.innerHeight;
    // 1 when the hero's top is at the bottom of the screen, 0 when its centre reaches the centre
    var t = (r.top + r.height / 2 - vh / 2) / (vh / 2 + r.height / 2);
    t = Math.max(0.12, Math.min(1, t));
    shot.style.setProperty('--t', t.toFixed(3));
  }

  var ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(function () { ticking = false; lightChip(); tilt(); });
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll);
  lightChip(); tilt();

  // ------------------------------------------------------------ C word reveal
  var cHero = $('.xc');
  if (cHero && !reduced && 'IntersectionObserver' in window) {
    var k = 0;
    $$('.xc-h > span', cHero).forEach(function (line) {
      var words = line.textContent.trim().split(/\s+/);
      line.innerHTML = words.map(function (w) { return '<span class="xw" style="--w:' + (k++) + '">' + esc(w) + '</span>'; }).join(' ');
    });
    $('.xc-h', cHero).setAttribute('aria-label', $('.xc-h', cHero).textContent);
    cHero.classList.add('is-anim');
    var cio = new IntersectionObserver(function (es) {
      if (es[0].isIntersecting) { cHero.classList.add('is-in'); cio.disconnect(); }
    }, { threshold: 0.35 });
    cio.observe(cHero);
  }

  // ------------------------------------------------------------ D count-up
  var dHero = $('.xd');
  if (dHero && !reduced && 'IntersectionObserver' in window) {
    var nums = $$('[data-to]', dHero);
    nums.forEach(function (b) { b.textContent = '0' + (b.getAttribute('data-suf') || ''); });
    var dio = new IntersectionObserver(function (es) {
      if (!es[0].isIntersecting) return;
      dio.disconnect();
      var t0 = performance.now();
      (function step(now) {
        var p = Math.min(1, (now - t0) / 1100), e = 1 - Math.pow(1 - p, 3);
        nums.forEach(function (b) { b.textContent = Math.round(+b.getAttribute('data-to') * e) + (b.getAttribute('data-suf') || ''); });
        if (p < 1) requestAnimationFrame(step);
      })(t0);
    }, { threshold: 0.4 });
    dio.observe(dHero);
  }
})();
